public class FreightRaterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("light letter", 150, FreightRater.costCents(new Letter(20)));
        check("heavy letter", 200, FreightRater.costCents(new Letter(101)));
        check("plain parcel", 500, FreightRater.costCents(new Parcel(100, false)));
        check("fragile parcel adds 25 percent", 625, FreightRater.costCents(new Parcel(100, true)));
        check("small pallet is flat rate", 4000, FreightRater.costCents(new Pallet(10)));
        check("big pallet charges the extra kilos", 6700, FreightRater.costCents(new Pallet(13)));

        Shipment oddity = new Shipment() {
        };
        String labels = FreightRater.labelFor(new Letter(5))
                + "|" + FreightRater.labelFor(new Parcel(10, false))
                + "|" + FreightRater.labelFor(new Parcel(10, true))
                + "|" + FreightRater.labelFor(new Pallet(2))
                + "|" + FreightRater.labelFor(oddity);
        check("labels for every kind", "LETTER|PARCEL|PARCEL-FRAGILE|PALLET|UNKNOWN", labels);

        List<Shipment> load = new ArrayList<>();
        load.add(new Letter(20));
        load.add(null);
        load.add(new Pallet(11));
        check("totalCents skips nulls", 5050, FreightRater.totalCents(load));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
