import java.util.List;

/**
 * TASK: Complete FreightRater using Java 17 pattern matching for instanceof
 * (for example: if (item instanceof Parcel p) { ... p.grams() ... }).
 * The Shipment interface and its three records above are provided -- do not
 * change them.
 *
 * Prices, all in whole cents:
 *   - Letter: 150, plus 50 more when grams > 100
 *   - Parcel: 300 + 2 per gram, and then 25% more when fragile
 *             (use cost = cost * 125 / 100, integer arithmetic)
 *   - Pallet: 4000, plus 900 for every kilo ABOVE 10
 *   - null, or any other kind of Shipment: 0
 *
 * labelFor returns "LETTER", "PARCEL", "PARCEL-FRAGILE", "PALLET", or
 * "UNKNOWN" for null and anything else. totalCents adds up a list, skipping
 * nulls, and returns 0 for a null list.
 *
 * Example: costCents(new Parcel(100, true)) is (300 + 200) * 125 / 100 = 625.
 */
interface Shipment {
}

record Letter(int grams) implements Shipment {
}

record Parcel(int grams, boolean fragile) implements Shipment {
}

record Pallet(int kilos) implements Shipment {
}

public class FreightRater {

    public static int costCents(Shipment item) {
        if (item instanceof Letter letter) {
            return letter.grams() > 100 ? 200 : 150;
        }
        if (item instanceof Parcel parcel) {
            int cost = 300 + 2 * parcel.grams();
            if (parcel.fragile()) {
                cost = cost * 125 / 100;
            }
            return cost;
        }
        if (item instanceof Pallet pallet) {
            int extra = pallet.kilos() > 10 ? pallet.kilos() - 10 : 0;
            return 4000 + 900 * extra;
        }
        return 0;
    }

    public static String labelFor(Shipment item) {
        if (item instanceof Letter) {
            return "LETTER";
        }
        if (item instanceof Parcel parcel) {
            return parcel.fragile() ? "PARCEL-FRAGILE" : "PARCEL";
        }
        if (item instanceof Pallet) {
            return "PALLET";
        }
        return "UNKNOWN";
    }

    public static int totalCents(List<Shipment> shipments) {
        if (shipments == null) {
            return 0;
        }
        int total = 0;
        for (Shipment item : shipments) {
            if (item != null) {
                total = total + costCents(item);
            }
        }
        return total;
    }
}
